pub async fn serve(client: Client, args: Args) -> Result<()> {
    let names = real_client_harness::Names::default();
    let url = std::env::var(names.get("engineUrlVariable"))?;
    let identity = PathBuf::from(std::env::var(names.get("identityDirVariable"))?);
    anyhow::ensure!(
        args.evidence.is_absolute(),
        "evidence path must be absolute"
    );
    let config = Config {
        client,
        program: args.client_program.unwrap_or_else(|| client.name().into()),
        helper: std::env::current_exe()?,
        evidence: args.evidence,
        cwd: std::env::current_dir()?,
        env: run_environment(crate::inherited_environment(), &url, &identity),
        url,
        timeout: Duration::from_secs(args.timeout_secs),
    };
    prepare(&config)?;
    let session = Arc::new(Mutex::new(Session::new(config)));
    let service = Wrapper(session.clone())
        .serve(rmcp::transport::stdio())
        .await?;
    let result = service.waiting().await;
    session.lock().await.shutdown().await;
    result?;
    Ok(())
}

async fn audit(State(stub): State<Stub>, request: Request, next: Next) -> Response {
    let id = stub.0.request_id.fetch_add(1, Ordering::SeqCst);
    let (parts, body) = request.into_parts();
    let bytes = match to_bytes(body, 4 * 1024 * 1024).await {
        Ok(b) => b,
        Err(_) => return StatusCode::PAYLOAD_TOO_LARGE.into_response(),
    };
    let body: Value = serde_json::from_slice(&bytes).unwrap_or(Value::Null);
    let token = parts
        .headers
        .get("authorization")
        .and_then(|s| s.to_str().ok())
        .and_then(|s| s.strip_prefix("Bearer "));
    let instance = token
        .and_then(|t| stub.0.identities.iter().find(|identity| identity.valid(t)))
        .map(|identity| identity.subject.clone());
    let valid = instance.is_some();
    let request_text = stub.redact(&String::from_utf8_lossy(&bytes));
    let headers: std::collections::BTreeMap<_, _> = [
        "mcp-session-id",
        "mcp-protocol-version",
        "mcp-method",
        "mcp-name",
        "origin",
        "accept",
        "content-type",
        "last-event-id",
    ]
    .into_iter()
    .filter_map(|name| {
        let values: Vec<_> = parts
            .headers
            .get_all(name)
            .iter()
            .map(|value| stub.redact(value.to_str().unwrap_or("[non-UTF8]")))
            .collect();
        (!values.is_empty()).then_some((name, values))
    })
    .collect();
    stub.0.log.event(json!({"kind":"request","id":id,"http_method":parts.method.as_str(),"body":request_text,"session":parts.headers.get("mcp-session-id").and_then(|s|s.to_str().ok()),"revision":parts.headers.get("mcp-protocol-version").and_then(|s|s.to_str().ok()),"headers":headers,"token_valid":valid,"instance":instance}));

